class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def search_bst(root, target):
    node = root
    while node is not None:
        if node.val == target:
            return node
        if target < node.val:
            node = node.left
        else:
            node = node.right
    return None
